import assert from 'node:assert/strict';import{resolve}from'node:path';
export async function extras({p,d,ir,teste,perfil,fase,out}){
 if(process.env.QA_EXTRA_CASO==='layout-completo'){
  const {layoutCompleto}=await import('./cadastros-layout-completo-20261118.mjs');
  return layoutCompleto({p,d,ir,teste,perfil,out});
 }
 const fechar=async()=>{await d().getByRole('button',{name:'Fechar janela',exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'})};
 const secao=async(texto)=>{const s=d().locator('summary').filter({hasText:texto}).first();if(await s.count()&&(await s.locator('..').getAttribute('open'))===null)await s.click()};
 await teste(perfil,'Serviços · reabrir edição usa ficha confirmada',async()=>{await ir(perfil,'catalogo');await p.getByRole('button',{name:'Novo serviço',exact:true}).click();await d().locator('[name=descricao]').fill('Serviço QA');await d().locator('[name=preco]').fill('150');await d().getByRole('button',{name:'Salvar cadastro',exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});const tempos=[];for(let i=0;i<2;i++){const t=performance.now();await p.getByRole('button',{name:'Editar',exact:true}).click();await d().locator('[name=descricao]').waitFor();tempos.push((performance.now()-t)/1000);await fechar()}const consultas=await p.evaluate(()=>window.qaChamadas.filter(c=>c.nome==='consultar_ficha_servico').length);if(fase==='depois')assert.equal(consultas,1);return{consultas,primeira:tempos[0],segunda:tempos[1]}});
 if(process.env.QA_EXTRA_CASO==='cache')return;
 await teste(perfil,'Funcionários · busca sem acentos e opcionais preservados',async()=>{await ir(perfil,'funcionarios');await p.getByRole('button',{name:'Novo funcionário',exact:true}).click();await d().locator('[name=nome]').fill('José QA');await secao('Contato e função');await d().locator('[name=funcao]').fill('Técnico');await d().locator('[name=email]').fill('qa@example.invalid');await secao('Contratação, salário');await d().locator('[name=salario]').fill('2500');await d().getByRole('button',{name:'Salvar funcionário',exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});await p.getByPlaceholder('Nome, função ou contato').fill(' jose ');if(fase==='depois')await p.getByRole('button',{name:'Abrir ficha de José QA',exact:true}).waitFor();else await p.getByPlaceholder('Nome, função ou contato').fill('José');await p.getByRole('button',{name:'Abrir ficha de José QA',exact:true}).click();await d().getByRole('button',{name:'Salvar funcionário',exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});const f=await p.evaluate(()=>window.qaDB.funcionarios[0]);assert.equal(f.salario_centavos,250000);assert.equal(f.email,'qa@example.invalid');assert.equal(f.funcao,'Técnico');return{}});
 await teste(perfil,'Fornecedores · opcionais recolhidos preservam dados',async()=>{await ir(perfil,'fornecedores');await p.getByRole('button',{name:'Novo fornecedor',exact:true}).click();await d().locator('[name=nome]').fill('Fornecedor QA');await secao('Mais informações');await d().locator('[name=email]').fill('qa@example.invalid');await d().locator('[name=endereco]').fill('Rua QA, 123');await d().getByRole('button',{name:'Salvar fornecedor',exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});await p.getByRole('button',{name:'Editar',exact:true}).click();await d().getByRole('button',{name:'Salvar fornecedor',exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'});const f=await p.evaluate(()=>window.qaDB.fornecedores[0]);assert.equal(f.endereco,'Rua QA, 123');assert.equal(f.email,'qa@example.invalid');return{}});
 for(const width of[320,390,768,1920])for(const [tela,novo]of[['funcionarios','Novo funcionário'],['fornecedores','Novo fornecedor'],['catalogo','Novo serviço']])await teste(perfil,`Layout ${tela} ${width}`,async()=>{await p.setViewportSize({width,height:844});await ir(perfil,tela);await p.getByRole('button',{name:novo,exact:true}).click();await d().locator('input[name]').first().waitFor();await p.evaluate(()=>document.fonts.ready);const v=await d().evaluate(e=>({pagina:document.documentElement.scrollWidth-innerWidth,dialogo:e.scrollWidth-e.clientWidth,fora:[...e.querySelectorAll('input,button,select,textarea,summary')].filter(n=>n.checkVisibility()).filter(n=>{const r=n.getBoundingClientRect();return r.left<0||r.right>innerWidth+1}).map(n=>n.tagName)}));assert(v.pagina<=1&&v.dialogo<=1);assert.deepEqual(v.fora,[]);if(['retifica','assistencia_celulares','manutencao_climatizacao','limpeza_geral'].includes(perfil)&&[390,1920].includes(width))await p.screenshot({path:resolve(out,`${perfil}-${tela}-${width}.png`)});await fechar();return{}});
 await p.setViewportSize({width:390,height:844});
}
